			assertThat(fallback.getValue("objects").stringValue()).isEqualTo("2");
			assertThat(fixture.rootOpens.get()).as("ordinary exact root streams must really admit this source")
					.isGreaterThan(0);
			fixture.metadata = true;
			fixture.rootOpens.set(0);
